actor WorkQueue {
    private var items: [WorkItem] = []
    private let max: Int

    func enqueue(_ item: WorkItem) async throws {
        guard items.count < max else { throw Error.full }
        items.append(item)
    }

    func dequeue() async -> WorkItem? {
        guard !items.isEmpty else { return nil }
        return items.removeFirst()
    }
}
```
Invariants: `count <= max`. Thread-safe via actor isolation.

